import React from 'react';

const BackgroundAnimation = () => {
  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100vw',
      height: '100vh',
      zIndex: -1,
      background: '#f8f9fa',
      overflow: 'hidden',
      pointerEvents: 'none'
    }}>
      <style>{`
        .gradient-blob {
          position: absolute;
          border-radius: 50%;
          filter: blur(60px);
          opacity: 0.7;
          animation: float-blob 20s infinite ease-in-out alternate;
        }
        @keyframes float-blob {
          0% { transform: translate(0, 0) scale(1); }
          33% { transform: translate(30px, -50px) scale(1.1); }
          66% { transform: translate(-20px, 20px) scale(0.9); }
          100% { transform: translate(0, 0) scale(1); }
        }
      `}</style>
      
      <div className="gradient-blob" style={{
        top: '-10%', left: '-10%', width: '50vw', height: '50vw',
        background: 'linear-gradient(135deg, #a8edea 0%, #fed6e3 100%)',
        animationDuration: '25s'
      }}></div>
      
      <div className="gradient-blob" style={{
        bottom: '-10%', right: '-10%', width: '60vw', height: '60vw',
        background: 'linear-gradient(135deg, #e0c3fc 0%, #8ec5fc 100%)',
        animationDuration: '30s', animationDelay: '-5s'
      }}></div>
      
      <div className="gradient-blob" style={{
        top: '40%', left: '40%', width: '40vw', height: '40vw',
        background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',
        transform: 'translate(-50%, -50%)',
        animationDuration: '22s', animationDelay: '-10s', opacity: 0.4
      }}></div>
      
      <div style={{
        position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
        backdropFilter: 'blur(80px)', WebkitBackdropFilter: 'blur(80px)', opacity: 0.6,
        background: 'rgba(255,255,255,0.3)'
      }}></div>
    </div>
  );
};

export default BackgroundAnimation;
